import{_ as o,c as l,o as e,a5 as s}from"./chunks/framework.DuCYAsAJ.js";const n="/my-blog/mysql/lock/suo1.png",a="/my-blog/mysql/lock/suo2.png",r="/my-blog/mysql/lock/suo3.png",i="/my-blog/mysql/lock/suo4.png",p="/my-blog/mysql/lock/suo5.png",d="/my-blog/mysql/lock/suo6.png",g="/my-blog/mysql/lock/suo7.png",c="/my-blog/mysql/lock/suo8.png",h="/my-blog/mysql/lock/suo9.png",u="/my-blog/mysql/lock/suo10.png",m="/my-blog/mysql/lock/suo14.png",k="/my-blog/mysql/lock/suo15.png",I=JSON.parse('{"title":"MySQL-锁机制","description":"","frontmatter":{"title":"MySQL-锁机制","date":"2026-01-10T00:00:00.000Z"},"headers":[],"relativePath":"posts/mysql/5.md","filePath":"posts/mysql/5.md","lastUpdated":1775711869000}'),b={name:"posts/mysql/5.md"};function E(y,t,_,q,S,A){return e(),l("div",null,[...t[0]||(t[0]=[s('<h3 id="什么是锁" tabindex="-1">什么是锁 <a class="header-anchor" href="#什么是锁" aria-label="Permalink to &quot;什么是锁&quot;">​</a></h3><p>锁是数据库系统区别于文件系统的一个关键特性，锁机制用于管理对共享资源的并发访问。在 innodb 引擎中会在行级别上对表数据上锁，也会在数据库内部其他多个地方使用锁，和 Oracle 的锁实现非常类似，提供一致性的非锁定读、行级锁支持。行级锁没有相关额外开销，并可以同时得到并发性和一致性。各个引擎的锁实现不同，如 MyISAM 引擎是表锁设计，并发情况下读锁没有问题，写锁性能差一些。</p><h3 id="lock-与-latch" tabindex="-1">lock 与 latch <a class="header-anchor" href="#lock-与-latch" aria-label="Permalink to &quot;lock 与 latch&quot;">​</a></h3><p><strong>latch</strong>（闩锁）是轻量级的锁，要求锁定的时间必须非常短，否则性能差，在 innodb 中可分为<strong>mutex</strong>和<strong>rwlock</strong>，用来保证并发中临界资源的正确性，通常没有死锁检测的机制。</p><p><strong>lock</strong>的对象是事务，用来锁定数据库中的对象，如表、页、行。一般对象仅在事务 commit 或 rollback 后释放。有死锁机制</p><p><img src="'+n+'" alt=""></p><p>通过 SHOW ENGINE INNODB MUTEX 进行查看 latch</p><p><img src="'+a+'" alt=""></p><h3 id="innodb-存储引擎中的锁" tabindex="-1">InnoDB 存储引擎中的锁 <a class="header-anchor" href="#innodb-存储引擎中的锁" aria-label="Permalink to &quot;InnoDB 存储引擎中的锁&quot;">​</a></h3><h4 id="锁的类型" tabindex="-1">锁的类型 <a class="header-anchor" href="#锁的类型" aria-label="Permalink to &quot;锁的类型&quot;">​</a></h4><p>共享锁 S：允许事务读一行数据</p><p>排他锁 X：允许事务删除或更新一行数据</p><p>锁兼容情况：</p><p><img src="'+r+'" alt=""></p><p>意向锁：Innodb 支持多粒度锁定，允许事务在行级锁和表级锁同时存在，意向锁将锁定的对象分为多个层次，可以将锁看成一棵树</p><p><img src="'+i+'" alt=""></p><p>对下层对象上锁首先要保证对上层对象上锁。比如事务 B 在对记录 r 加 X 锁之前，已经有事务 A 对表 1 进行了 S 表锁，所以事务 B 需要在表 1 上加 IX 锁（意向排他锁），由于不兼容，所以事务 B 需要等待事务 A 的表锁操作完成。</p><p>意向锁的兼容性</p><p><img src="'+p+'" alt=""></p><p>用户可以通过 SHOW ENGINE INNODB STATUS\\G;查看当前锁请求的信息</p><p>从 InnoDB1.0 开始，可以通过以下三张表监控当前事务并分析可能存在的锁问题</p><p><img src="'+d+'" alt=""></p><p><img src="'+g+'" alt=""></p><p><img src="'+c+'" alt=""></p><h4 id="一致性非锁定读" tabindex="-1">一致性非锁定读 <a class="header-anchor" href="#一致性非锁定读" aria-label="Permalink to &quot;一致性非锁定读&quot;">​</a></h4><p>Innodb 通过行多版本控制的方式来读取当前执行时间数据库中行的数据。在执行 select 时不加锁，如果读取的行正在被 delete 或者 update，innodb 不会等待行被释放，而是去读取该行的一个快照数据</p><p><strong>实现机制：MVCC+Undo Log</strong></p><p>undo 在事务中回滚数据，因此快照数据本身是没有额外开销的。另外读快照数据不需要上锁，大大提高了数据库的并发性。这是 Innodb 引擎的默认读取方式</p><p>但是在不同事务隔离级别下，读取的方式不同</p><p>快照数据其实就是当前行数据之前的历史记录，每行记录有多个快照数据，因此称之为多版本并发控制</p><p><strong>READ COMMITTED（读已提交） 和 REPEATABLE READ（可重复读，默认）：使用非锁定一致性读，但是对于快照数据定义，前者总是读取被锁定行的最新一份快照数据，后者总是读取事务开始时的行数据版本</strong></p><h4 id="一致性锁定读" tabindex="-1">一致性锁定读 <a class="header-anchor" href="#一致性锁定读" aria-label="Permalink to &quot;一致性锁定读&quot;">​</a></h4><p>某些情况用户需要显式地对读取操作进行加锁保证数据一致性</p><p>支持两种一致性锁定读操作：</p><ol><li>SELECT...FOR UPDATE</li><li>SELECT...LOCK IN SHARE MODE</li></ol><p>1 对读取的行记录加一个 X 锁，其他事务不能对已锁定的行加上任何锁</p><p>2 对读取的行记录加一个 S 锁，其他事务可以向被锁定的行加 S 锁，加 X 锁会被阻塞</p><h4 id="自增长与锁" tabindex="-1">自增长与锁 <a class="header-anchor" href="#自增长与锁" aria-label="Permalink to &quot;自增长与锁&quot;">​</a></h4><p>你一定用过<code>AUTO_INCREMENT</code>。在单机单线程下它很简单，但在高并发下，如果有 1000 个线程同时插入数据，InnoDB 如何保证 ID 不重复且连续？</p><p><strong>为什么 ID 会不连续（出现空洞）？事务回滚</strong></p><ul><li>InnoDB 的自增计数器是在内存中的。</li><li>事务 A 申请了 ID=5，然后回滚了。</li><li>自增计数器<strong>不会回退</strong>（为了性能，也为了避免锁竞争）。</li><li>下一个事务 B 申请到的就是 ID=6。ID=5 就永远消失了。</li></ul><p>这就涉及到了一个特殊的锁机制：<strong>AUTO-INC Locking</strong>。</p><p>先看自增长的插入类型：</p><p><img src="'+h+'" alt=""></p><p>为了解决自增问题，InnoDB 提供了一个可配置的参数：<code>innodb_autoinc_lock_mode</code>。这个参数决定了锁的“粒度”和“性能”。它有三种模式</p><p><img src="'+u+'" alt=""></p><p>另外 MyISAM 时表锁设计，自增长不需要考虑并发插入</p><p>在 Innodb 中自增长值的列必须是索引，同时必须是索引的第一个列，否则会抛出异常</p><p>InnoDB 强制规定：<strong>子表的外键列，必须有索引。</strong> 如果你没建，它会自动帮你建一个。</p><ul><li><strong>原因</strong>： 如果子表的外键列没有索引，当你要在父表中删除一行数据（比如删除一个用户）时，为了检查“有没有订单关联这个用户”，InnoDB 就不得不对子表进行 <strong>全表扫描 (Full Table Scan)</strong>。</li><li>这将导致父表的删除操作极其缓慢，并且会锁住子表的大量数据。</li></ul><h4 id="外键与锁" tabindex="-1">外键与锁 <a class="header-anchor" href="#外键与锁" aria-label="Permalink to &quot;外键与锁&quot;">​</a></h4><p>外键主要用于引用完整性的约束检查</p><p>InnoDB 强制规定：<strong>子表的外键列，必须有索引。</strong> 如果你没建，它会自动帮你建一个。</p><ul><li><strong>原因</strong>： 如果子表的外键列没有索引，当你要在父表中删除一行数据（比如删除一个用户）时，为了检查“有没有订单关联这个用户”，InnoDB 就不得不对子表进行 <strong>全表扫描 (Full Table Scan)</strong>。</li><li>这将导致父表的删除操作极其缓慢，并且会锁住子表的大量数据。</li></ul><p>假设你有两张表：</p><p><strong>父表</strong>:<code>users (id, name)</code></p><p><strong>子表</strong>:<code>orders (id, user_id, amount)</code>，其中 <code>user_id</code> 是外键。</p><p>执行以下 SQL ：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INSERT INTO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders (id, user_id, amount) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VALUES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>InnoDB 不仅要在 <code>orders</code> 表里写数据，它必须去 <code>users</code> 表里检查 <code>id=1</code> 是否存在。 <strong>关键点来了</strong>： 这种检查不仅仅是“读一下”，而是必须加锁！它会在父表 (<code>users</code>) 的 <code>id=1</code> 这行上加一个 <strong>S 锁 (共享锁 / 读锁)</strong>。</p><ul><li><strong>原因</strong>： 必须保证在我插入订单的瞬间，这个用户不能被删掉。</li></ul><p>这种隐形的 S 锁，非常容易导致死锁。</p><ol><li><strong>事务 A (插入子表)</strong>:<code>INSERT INTO orders ... VALUES (..., user_id=1)</code>。 <ul><li><em>结果：</em> 事务 A 持有 <code>users</code> 表 id=1 的 <strong>S 锁</strong>。</li></ul></li><li><strong>事务 B (更新父表)</strong>:<code>UPDATE users SET name=&#39;NewName&#39; WHERE id=1</code>。 <ul><li><em>结果：</em> 事务 B 想要 <code>users</code> 表 id=1 的 <strong>X 锁</strong> (排他锁)。</li><li><em>冲突：</em> X 锁被 A 的 S 锁阻塞，B 进入等待。</li></ul></li><li><strong>事务 A (继续操作)</strong>: 如果事务 A 接着想 <code>UPDATE users WHERE id=1</code>... <ul><li><em>结果：</em> A 想要升级自己的 S 锁为 X 锁。但发现 B 正在排队等 X 锁（或者已经有其他意向锁）。</li><li><strong>BOOM! 死锁发生。</strong></li></ul></li></ol><h3 id="锁的算法" tabindex="-1">锁的算法 <a class="header-anchor" href="#锁的算法" aria-label="Permalink to &quot;锁的算法&quot;">​</a></h3><h4 id="行锁的-3-种算法" tabindex="-1">行锁的 3 种算法 <a class="header-anchor" href="#行锁的-3-种算法" aria-label="Permalink to &quot;行锁的 3 种算法&quot;">​</a></h4><ul><li>Record Lock：单个行的锁，总是会去锁住索引记录，如果没有创建索引，会使用隐式的主键进行锁定</li><li>Gap Lock：间隙锁，锁定一个范围（开区间），但不包括记录本身（解决了幻读）</li><li>Next-Key Lock：Gap Lock+Record Lock，锁定一个范围，并且锁定记录本身（左开右闭，同样有 previous-key locking 技术左闭右开）</li></ul><h4 id="解决-phantom-problem-幻读" tabindex="-1">解决 Phantom Problem（幻读） <a class="header-anchor" href="#解决-phantom-problem-幻读" aria-label="Permalink to &quot;解决 Phantom Problem（幻读）&quot;">​</a></h4><p><strong>幻读</strong>：同一事务连续执行两次相同的 SQL 结果却不同，第二次 SQL 可能会返回不存在的行。</p><p><strong>举例</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;"><strong>时间轴</strong></th><th style="text-align:left;"><strong>事务 A</strong></th><th style="text-align:left;"><strong>事务 B</strong></th><th style="text-align:left;"><strong>结果</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>T1</strong></td><td style="text-align:left;"><code>BEGIN;</code></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>T2</strong></td><td style="text-align:left;"><code>SELECT * FROM users WHERE age &gt; 20;</code><br><em>(假设查到了 2 人：Alice(25), Bob(30))</em></td><td style="text-align:left;"></td><td style="text-align:left;">A 以为只有 2 人</td></tr><tr><td style="text-align:left;"><strong>T3</strong></td><td style="text-align:left;"></td><td style="text-align:left;"><code>INSERT INTO users (name, age) VALUES (&#39;Charlie&#39;, 22);</code><br><code>COMMIT;</code></td><td style="text-align:left;"><strong>B 成功插入了一个 age=22 的人</strong></td></tr><tr><td style="text-align:left;"><strong>T4</strong></td><td style="text-align:left;"><code>SELECT * FROM users WHERE age &gt; 20;</code><br><em>(这次查到了 3 人：Alice, Bob, <strong>Charlie</strong>)</em></td><td style="text-align:left;"></td><td style="text-align:left;"><strong>Charlie 是哪来的？</strong></td></tr></tbody></table><p>InnoDB 默认事务隔离级别是 RR（可重复读），在 SQL 标准下会发生幻读，但是 InnoDB 通过 <strong>Next-key Lock</strong> 在范围内加锁从而避免幻读（想要出现上述情况，得设置成 READ COMMITTED）。</p><p>同时该机制在应用层实现唯一性的检查。</p><p>两个事务（A 和 B）并发插入一个数据 <code>4</code>，为了防止重复，它们决定先查后插。</p><ul><li>A 查 <code>b=4</code>（假设不存在）。拿到了一把 <strong>S 锁 (共享锁)</strong>，这是一个 <strong>Gap Lock (间隙锁)</strong>。</li><li>B 也查 <code>b=4</code>。<strong>S 锁和 S 锁是兼容的！</strong> 间隙锁也是兼容的！B 也拿到了这块地的 S 锁。</li><li>A 想要写入数据。这需要升级为 <strong>X 锁</strong>。但发现 B 手里拿着 S 锁。A 被阻塞，只能等待 B 释放 S 锁。</li><li>B 也想要写入数据，也需要升级为 X 锁。但发现 A 手里拿着 S 锁。B 被阻塞，只能等待 A 释放 S 锁。</li></ul><p><strong>怎么解决？</strong> 不要用 <code>LOCK IN SHARE MODE</code> (S 锁) 做检查。直接用 <strong><code>SELECT ... FOR UPDATE</code></strong> <strong>(X 锁)</strong> 或者利用数据库的 <strong>唯一索引约束</strong> 让数据库自己去报错，而不是在业务层手动 check。</p><h3 id="锁问题" tabindex="-1">锁问题 <a class="header-anchor" href="#锁问题" aria-label="Permalink to &quot;锁问题&quot;">​</a></h3><h4 id="脏读" tabindex="-1">脏读 <a class="header-anchor" href="#脏读" aria-label="Permalink to &quot;脏读&quot;">​</a></h4><ul><li><p><strong>脏页</strong>：在缓冲池中已经被修改，但是没有刷新到磁盘中的页，但是日志都已经被写入重做日志文件。</p></li><li><p><strong>脏数据</strong>：事务对缓冲池中行记录的修改，并且没有被提交。</p></li><li><p>对于脏页的读取，是最终一致性，不影响数据库的可用性。</p></li><li><p>对于脏数据的读取，即为一个事务读取到另一个事务未提交的数据，违反了事务的隔离性。</p></li><li><p><strong>脏读</strong>：当前事务读取到另外事务未提交的数据。</p></li></ul><p>上述例子中，事务隔离级别为 READ UNCOMMITTED（读未提交），所以会产生脏读（生产环境下不常出现，因为事务隔离级别基本是 RR）。</p><h4 id="不可重复读" tabindex="-1">不可重复读 <a class="header-anchor" href="#不可重复读" aria-label="Permalink to &quot;不可重复读&quot;">​</a></h4><ul><li><strong>定义</strong>：一个事务内多次读取同一数据集合，因为另一事务的修改而导致的结果不同。</li><li><strong>区别</strong>：不可重复读和脏读的区别是：前者读到的是已提交的数据，后者读到的是未提交的数据。</li></ul><p>和上一个例子的区别就是这里发生了提交。</p><p>不可重复读的问题是可接受的，因为读到的是已提交的数据。因此很多数据库事务默认隔离级别是 READ COMMITTED，允许不可重复读。</p><p>InnoDB 中通过 Next-key Lock 避免不可重复读。</p><h4 id="丢失更新" tabindex="-1">丢失更新 <a class="header-anchor" href="#丢失更新" aria-label="Permalink to &quot;丢失更新&quot;">​</a></h4><p>一个事务的更新操作会被另一个事务的更新操作所覆盖。</p><p>例如：T1 更新行记录 r 为 v1，T2 更新行记录为 v2，T1 提交，T2 提交。</p><p>但是数据库在任何隔离级别下，都不会导致理论意义上的丢失更新问题（因为锁）。</p><p>要避免丢失更新的发生，需要让事务变成串行化，而不是并行操作：</p><ol><li><strong>数据库层面</strong>：InnoDB 自动加了锁。多个事务都想修改同一行时，数据库会让后面的排队。<strong>根本不可能</strong>发生“两人同时写进去”的情况。</li><li><strong>业务层面</strong>：先读出来余额 100，在内存里算 100-10，写回去 90。都读到了 100，算出了 90，最后余额变成 90。所以读的时候就告诉数据库要修改它 —— <strong><code>SELECT ... FOR UPDATE</code></strong>。</li></ol><h4 id="阻塞" tabindex="-1">阻塞 <a class="header-anchor" href="#阻塞" aria-label="Permalink to &quot;阻塞&quot;">​</a></h4><p>不同事务之间的锁需要等待彼此的释放。</p><ul><li><code>innodb_lock_wait_timeout</code>（动态，可以在运行时调整）：负责控制等待的时间，默认 50 秒。</li><li><code>innodb_rollback_on_timeout</code>（静态，不能在启动时调整）：负责设定是否在等待超时时对进行中的事务进行回滚操作，默认关闭。</li></ul><p>发生超时时，MySQL 会抛出 1205 错误。</p><p>默认 InnoDB 不会回滚超时引发的错误异常，大部分情况都不会对异常进行回滚（用户必须判断是否需要 commit 还是 rollback）。</p><h3 id="死锁" tabindex="-1">死锁 <a class="header-anchor" href="#死锁" aria-label="Permalink to &quot;死锁&quot;">​</a></h3><h4 id="死锁的概念" tabindex="-1">死锁的概念 <a class="header-anchor" href="#死锁的概念" aria-label="Permalink to &quot;死锁的概念&quot;">​</a></h4><p>死锁是指两个或以上的事务在执行过程中，因争夺锁资源而造成的一种相互等待的现象。</p><p>解决死锁最简单的方式是不要有等待，将任何等待都转化为回滚，并且事务重新开始，但是并发性能会下降。</p><p>最简单的一种方法是超时回滚，但是倘若超时的事务占比权重较大就不合适，所花时间就比较多。</p><p>除了超时机制，数据库普遍采用 <strong>wait-for-graph（等待图）</strong> 进行死锁检测，该方式保存两种信息：<strong>锁的信息链表，事务等待链表</strong>，构造出一张图，如果存在回路就代表有死锁，通常来说 InnoDB 会选择回滚 undo 量最小的事务。</p><p>该方法通常采用深度优先算法实现，用非递归方式实现。</p><h4 id="死锁概率" tabindex="-1">死锁概率 <a class="header-anchor" href="#死锁概率" aria-label="Permalink to &quot;死锁概率&quot;">​</a></h4><p>从纯概率论的角度，死锁概率极低。</p><p>假设数据库有 个事务同时在跑，每个事务操作 行数据，数据总量是 。且事务操作的数据占总数据的一小部分（）。</p><ul><li>一个事务获得一把锁需要等待的概率是非常小的（因为数据总量 很大）。</li><li>死锁是“循环等待”（A 等 B，B 等 A），这意味着需要 <strong>连续发生两次特定的等待</strong>。</li><li>概率本身就很小的事件，还要连续发生两次，其概率就是“小概率的平方”，所以非常非常小。</li></ul><p><strong>死锁概率公式 (仅作参考)</strong></p><ul><li>: 系统中事务的数量（并发度）</li><li>: 每个事务操作的数据行数（事务长度）</li><li>: 数据库总的数据行数（数据规模）</li></ul><p><strong>影响死锁概率的三大因素</strong></p><ol><li>系统中事务的数量 (****) 越多，死锁概率越大。</li><li>每个事务操作的数量 (****) 越多，死锁概率越大。事务要尽量短小。</li><li>操作数据的集合 (****) 越小，死锁概率越大。</li></ol><h4 id="死锁的示例" tabindex="-1">死锁的示例 <a class="header-anchor" href="#死锁的示例" aria-label="Permalink to &quot;死锁的示例&quot;">​</a></h4><p>死锁只存在于并发情况中</p><p><strong>AB-BA 死锁</strong></p><p><img src="'+m+'" alt=""></p><p>另一种死锁</p><p><strong>表数据</strong>： 只有一列 a，包含记录 1，2，4</p><p><img src="'+k+'" alt=""></p><p>这是一张经典的<strong>Next-Key Lock</strong>导致的死锁图表</p><p>死锁触发（时间点 5）会话 B 虽然在等待 a=4 的行锁，但它为了保证“可重复读”的语义，实际上已经隐式地表达了对 <code>(2, 4]</code> 范围的锁定意图。A 想要往 <code>(2, 4)</code> 里面插数据。如果允许 A 插入 3，等 B 拿到锁读取时，就会凭空多出一个 3，发生幻读</p><p>InnoDB 选择回滚 A，虽然 A 已经在工作了，undo log 记录大</p><h3 id="锁升级" tabindex="-1">锁升级 <a class="header-anchor" href="#锁升级" aria-label="Permalink to &quot;锁升级&quot;">​</a></h3><p>锁升级是指将当前锁的粒度降低，即将多个行锁升级为页锁，或者将页锁升级为表锁。锁是一种稀缺资源，锁升级可以避免开销</p><p>SQL Server 在 2005 之后支持了行锁，但是设计和 Innodb 完全不同，以下情况会发生锁升级</p><ol><li>由一个单独的 SQL 语句在一个对象上持有的锁的数量超过了阈值，默认这个阈值为 5000。如果是不同对象，不会发生锁升级</li><li>所资源占用的内存超过了激活内存的 40%时就会发生锁升级</li></ol><p>但是 InnoDB 中不存在锁升级问题，它是根据每个事务访问的每个页对锁进行管理的，采用内部维护一个位图的方式。因此不管一个事务锁住页中的多少记录，开销都是一致的</p>',125)])])}const x=o(b,[["render",E]]);export{I as __pageData,x as default};
